<?php
declare(strict_types=1);
require_once __DIR__.'/includes/bootstrap.php';require_role('user');
$stmt=db()->prepare('SELECT ar.*,r.report_name,r.original_filename,r.keyword,mr.patient_label,o.username owner_username FROM access_requests ar JOIN reports r ON r.id=ar.report_id JOIN medical_records mr ON mr.id=r.medical_record_id JOIN data_owners o ON o.id=mr.owner_id WHERE ar.user_id=? ORDER BY ar.created_at DESC');$stmt->execute([user()['id']]);$requests=$stmt->fetchAll();
$pageTitle='My Access Requests';require __DIR__.'/header.php';
?>
<h1>My Access Requests</h1><p class="lead">Approved requests include a user-facing authorization token. This token authorizes server-side decryption; it is not the AES master key.</p>
<section class="card"><div class="table-wrap"><table><thead><tr><th>Owner / patient</th><th>Report</th><th>Status</th><th>Authorization</th></tr></thead><tbody><?php if(!$requests):?><tr><td colspan="4">You have not requested any reports.</td></tr><?php endif;?>
<?php foreach($requests as $request):?><tr><td>@<?=e($request['owner_username'])?><br><?=e($request['patient_label'])?></td><td><?=e($request['report_name'])?><br><span class="muted"><?=e($request['keyword'])?></span></td><td><span class="badge badge-<?=e($request['status'])?>"><?=e($request['status'])?></span></td><td><?php if($request['status']==='approved'&&$request['token_secret']):?><?php try{$token=decrypt_value($request['token_secret'],'access-token:'.$request['id']);}catch(Throwable $exception){$token='Token unavailable; ask the owner to approve again.';}?><p class="compact"><span class="token"><?=e($token)?></span></p><form method="post" action="<?=e(url('authorized_report.php'))?>"><?=csrf_field()?><input type="hidden" name="request_id" value="<?=e($request['id'])?>"><div class="field"><label for="token-<?=e($request['id'])?>">Enter authorization token</label><input id="token-<?=e($request['id'])?>" name="access_token" required autocomplete="off"></div><div class="actions"><button class="btn btn-small" name="mode" value="view" type="submit">View Decrypted Report</button><button class="btn btn-small btn-secondary" name="mode" value="download" type="submit">Download</button></div></form><?php elseif($request['status']==='rejected'):?>Access denied. You may request again from the search page.<?php else:?>Waiting for the Data Owner's decision.<?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section>
<?php require __DIR__.'/footer.php';?>
